fetchEntries: async () => {
  set({ isLoading: true, error: null })
  try {
    const res = await fetch('https://api.programiz.pro/api/Demo/v1/journal-entries')
    const data = await res.json()
    set({ entries: data, isLoading: false })
  } catch (err) {
    set({ error: err.message, isLoading: false })
  }
}
